#include <cstdio>

static int g_coInit = 0, g_coUninit = 0;
static void CoInitialize_() { ++g_coInit; }
static void CoUninitialize_() { ++g_coUninit; }

class CMsg {
public:
    unsigned int uMsg;
    unsigned int dwFlags;
    void*        lpParam;
    void*        pEvent;
    CMsg() : uMsg(0), dwFlags(0), lpParam(0), pEvent(0) {}
};

