    };
    class CNodeCache {
    public:
        CNodeCache() : m_iCacheSize(4), m_iUsed(0), m_pHead(0) {}
        void AddToCache(CNode* pNode)
        {
            pNode->SetNext(m_pHead);
            m_pHead = pNode;
            m_iUsed++;
        }
        CNode* RemoveFromCache()
        {
            CNode* pNode = m_pHead;
            if (pNode != 0) {
